#!/usr/bin/env node
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i += 2) {
    const key = argv[i];
    if (!key?.startsWith('--') || i + 1 >= argv.length) {
      throw new Error(`无效参数: ${key || ''}`);
    }
    args[key.slice(2)] = argv[i + 1];
  }
  for (const required of ['sidebar', 'docs-root', 'output']) {
    if (!args[required]) throw new Error(`缺少参数 --${required}`);
  }
  return args;
}

function chooseSidebar(moduleValue) {
  if (Array.isArray(moduleValue)) return moduleValue;
  if (!moduleValue || typeof moduleValue !== 'object') return null;
  const arrays = Object.values(moduleValue).filter(Array.isArray);
  if (!arrays.length) return null;
  return arrays[0];
}

async function loadSidebar(sidebarPath) {
  const extension = path.extname(sidebarPath).toLowerCase();
  if (extension === '.json') {
    const parsed = JSON.parse(fs.readFileSync(sidebarPath, 'utf8'));
    return chooseSidebar(parsed);
  }

  const source = fs.readFileSync(sidebarPath, 'utf8');
  if (/\bmodule\.exports\b/.test(source)) {
    const temporary = path.join(
      path.dirname(sidebarPath),
      `.pdf-action-sidebar-${process.pid}${path.extname(sidebarPath) || '.cjs'}.cjs`,
    );
    try {
      fs.writeFileSync(temporary, source, 'utf8');
      const module = await import(pathToFileURL(temporary).href);
      return chooseSidebar(module.default || module);
    } finally {
      fs.rmSync(temporary, { force: true });
    }
  }

  const temporary = path.join(
    path.dirname(sidebarPath),
    `.pdf-action-sidebar-${process.pid}.mjs`,
  );
  try {
    fs.writeFileSync(temporary, source, 'utf8');
    const module = await import(pathToFileURL(temporary).href);
    return chooseSidebar(module.default || module);
  } finally {
    fs.rmSync(temporary, { force: true });
  }
}

function normalizeId(value) {
  return String(value).replaceAll('\\', '/').replace(/^\/+/, '').replace(/\.(md|mdx)$/i, '');
}

function resolveDoc(docsRoot, docId) {
  const normalized = normalizeId(docId);
  const candidates = [
    `${normalized}.md`,
    `${normalized}.mdx`,
    `${normalized}/index.md`,
    `${normalized}/index.mdx`,
  ];
  if (normalized === '') candidates.unshift('index.md', 'index.mdx');
  for (const relative of candidates) {
    const absolute = path.join(docsRoot, relative);
    if (fs.existsSync(absolute) && fs.statSync(absolute).isFile()) {
      return relative.replaceAll(path.sep, '/');
    }
  }
  return null;
}

function readTitle(filePath) {
  const text = fs.readFileSync(filePath, 'utf8');
  const match = text.match(/^---\s*\n([\s\S]*?)\n---/);
  if (!match) return null;
  const title = match[1].match(/^title:\s*(.+?)\s*$/m);
  if (!title) return null;
  return title[1].replace(/^['"]|['"]$/g, '').trim() || null;
}

function listMarkdownFiles(directory) {
  if (!fs.existsSync(directory)) return [];
  return fs.readdirSync(directory, { withFileTypes: true })
    .flatMap((entry) => {
      const absolute = path.join(directory, entry.name);
      if (entry.isDirectory()) {
        if (['node_modules', '_assets', 'static'].includes(entry.name)) return [];
        return listMarkdownFiles(absolute);
      }
      return /\.(md|mdx)$/i.test(entry.name) ? [absolute] : [];
    });
}

function autogeneratedItems(docsRoot, dirName) {
  const directory = path.resolve(docsRoot, dirName || '.');
  if (!directory.startsWith(path.resolve(docsRoot))) {
    throw new Error(`autogenerated 目录越界: ${dirName}`);
  }
  return listMarkdownFiles(directory)
    .map((absolute) => {
      const relative = path.relative(docsRoot, absolute).replaceAll(path.sep, '/');
      return { relative, title: readTitle(absolute) || path.basename(absolute, path.extname(absolute)) };
    })
    .sort((a, b) => a.relative.localeCompare(b.relative, 'zh-CN'))
    .map(({ relative, title }) => ({ label: title, path: relative }));
}

function convertItems(items, docsRoot, visited, warnings) {
  const output = [];
  for (const item of items || []) {
    if (typeof item === 'string') {
      const resolved = resolveDoc(docsRoot, item);
      if (!resolved) {
        warnings.push(`找不到侧边栏文档: ${item}`);
        continue;
      }
      if (!visited.has(resolved)) {
        visited.add(resolved);
        output.push({ label: path.basename(resolved, path.extname(resolved)), path: resolved });
      }
      continue;
    }
    if (!item || typeof item !== 'object') continue;

    if (item.type === 'category') {
      const children = convertItems(item.items, docsRoot, visited, warnings);
      if (item.link?.type === 'doc' && item.link.id) {
        const linked = resolveDoc(docsRoot, item.link.id);
        if (linked && !visited.has(linked)) {
          visited.add(linked);
          children.unshift({ label: item.label || readTitle(path.join(docsRoot, linked)) || item.label, path: linked });
        }
      }
      if (children.length) output.push({ label: item.label || '未命名分组', items: children });
      continue;
    }

    if (item.type === 'autogenerated') {
      const generated = autogeneratedItems(docsRoot, item.dirName)
        .filter((entry) => {
          if (visited.has(entry.path)) return false;
          visited.add(entry.path);
          return true;
        });
      if (generated.length) output.push(...generated);
      continue;
    }

    if (item.type === 'doc' || item.id) {
      const resolved = resolveDoc(docsRoot, item.id);
      if (!resolved) {
        warnings.push(`找不到侧边栏文档: ${item.id}`);
        continue;
      }
      if (visited.has(resolved)) continue;
      visited.add(resolved);
      const label = item.label || readTitle(path.join(docsRoot, resolved)) || path.basename(resolved, path.extname(resolved));
      output.push({ label, path: resolved });
      continue;
    }

    if (item.type === 'link') {
      warnings.push(`跳过侧边栏外链: ${item.href || item.label || ''}`);
      continue;
    }
    if (item.type === 'html') continue;
    warnings.push(`跳过不支持的侧边栏项: ${item.type || '(unknown)'}`);
  }
  return output;
}

async function main() {
  const args = parseArgs(process.argv);
  const sidebarPath = path.resolve(args.sidebar);
  const docsRoot = path.resolve(args['docs-root']);
  const sidebar = await loadSidebar(sidebarPath);
  if (!Array.isArray(sidebar)) throw new Error('侧边栏文件没有导出数组');

  const visited = new Set();
  const warnings = [];
  const items = convertItems(sidebar, docsRoot, visited, warnings);
  if (!items.length) throw new Error('侧边栏转换后没有有效文档');

  for (const warning of warnings) console.error(`::warning::${warning}`);
  fs.writeFileSync(
    path.resolve(args.output),
    JSON.stringify({ sidebar: sidebarPath, items }, null, 2),
    'utf8',
  );
}

main().catch((error) => {
  console.error(error.stack || String(error));
  process.exitCode = 1;
});
